import pandas as pd

COLUMNS = ["date", "account", "amount"]


def build_ledger(entries):
    # DataFrame.append was removed in pandas 2.0; build the frame in one go.
    rows = [(date, account, amount) for date, account, amount in entries]
    ledger = pd.DataFrame(rows, columns=COLUMNS, dtype=object)
    ledger["amount"] = ledger["amount"].astype(float)
    return ledger.reset_index(drop=True)


def balance(ledger, account):
    return float(ledger.loc[ledger["account"] == account, "amount"].sum())

