import numpy as np


def brighten(pixels, amount):
    # Compute in a wide signed type: under NumPy 2 (NEP 50) uint8 + int stays
    # uint8 and would wrap around / overflow instead of clipping.
    widened = np.asarray(pixels).astype(np.int64) + int(amount)
    return np.clip(widened, 0, 255).astype(np.uint8)


def mean_brightness(pixels):
    # Accumulate in a wide type so the sum cannot overflow uint8.
    total = int(np.asarray(pixels).sum(dtype=np.int64))
    return round(total / pixels.size, 2)

