import networkx as nx
import numpy as np


def build_graph(edges):
    graph = nx.Graph()
    graph.add_weighted_edges_from(edges)
    return graph


def adjacency(graph, nodes):
    return nx.to_numpy_array(graph, nodelist=nodes).tolist()


def two_step(graph, nodes):
    matrix = nx.to_numpy_array(graph, nodelist=nodes)
    # ndarray: `*` is elementwise, so use `@` for the matrix product.
    return (matrix @ matrix).tolist()


def from_rows(rows):
    return nx.from_numpy_array(np.asarray(rows))


def describe(graph):
    return (
        f"{type(graph).__name__} with {graph.number_of_nodes()} nodes "
        f"and {graph.number_of_edges()} edges"
    )

