import pandas as pd


def price_at(prices, items):
    items = list(items)
    products = [product for product, _ in items]
    stores = [store for _, store in items]
    row_idx = prices.index.get_indexer(products)
    col_idx = prices.columns.get_indexer(stores)
    for label, idx in zip(products, row_idx):
