import io

import pandas as pd


def load_values(csv_text):
    # `squeeze=` was removed from read_csv in pandas 2.0; take the single
    # column explicitly so we always get a Series (even with one row).
    return pd.read_csv(io.StringIO(csv_text)).iloc[:, 0]


def spread(values):
    # Series.mad() was removed in pandas 2.0; mean absolute deviation,
    # skipping missing values.
    values = values.dropna()
    return round(float((values - values.mean()).abs().mean()), 4)


def summary(csv_text):
    values = load_values(csv_text)
    return {"count": int(values.count()), "mean": round(float(values.mean()), 4), "spread": spread(values)}

