import io

import pandas as pd


def load_values(csv_text):
    # `squeeze=True` was removed from read_csv in pandas 2.0. Squeeze only the
    # columns axis so a single-row file still yields a Series, not a scalar.
    return pd.read_csv(io.StringIO(csv_text)).squeeze("columns")


def spread(values):
    # Series.mad() was removed in pandas 2.0; compute mean absolute deviation
    # around the mean, ignoring missing values (as mad(skipna=True) did).
    values = values.dropna()
    return round(float((values - values.mean()).abs().mean()), 4)


def summary(csv_text):
    values = load_values(csv_text)
    return {"count": int(values.count()), "mean": round(float(values.mean()), 4), "spread": spread(values)}

