def text_columns(frame):
    # pandas >= 3 stores text in the dedicated "str" dtype rather than object;
    # is_string_dtype on the Series handles both (for object columns it checks
    # the values are strings, ignoring missing values).
    return [column for column in frame.columns if is_string_dtype(frame[column])]


def normalise_text(frame):
    out = frame.copy()
    for column in text_columns(out):
        out[column] = out[column].str.strip().str.lower()
    return out

from pandas.api.types import is_object_dtype, is_string_dtype


def _is_text(series):
    # pandas >= 3 stores text in the dedicated "str" dtype by default; object
    # columns can still hold text, so check their non-missing values are strings.
    if is_object_dtype(series.dtype):
        values = series.dropna()
        return all(isinstance(value, str) for value in values)
    return is_string_dtype(series.dtype)


