import numpy as np


def brighten(pixels, amount):
    # Compute in a wide signed integer type: under numpy 2 (NEP 50) adding a
    # Python int to a uint8 array stays uint8 and would wrap around (or raise
    # for out-of-range scalars such as negative amounts).
    widened = np.asarray(pixels).astype(np.int64) + int(amount)
    return np.clip(widened, 0, 255).astype(np.uint8)


def mean_brightness(pixels):
    # Accumulate in a wide type to avoid uint8 overflow.
    total = int(np.asarray(pixels, dtype=np.int64).sum())
    return round(float(total / pixels.size), 2)

