import numpy as np


def brighten(pixels, amount):
    # Widen before adding: under NumPy 2 (NEP 50) uint8 + Python int stays
    # uint8 and wraps (or raises for out-of-range ints such as negatives).
    widened = pixels.astype(np.int64) + int(amount)
    return np.clip(widened, 0, 255).astype(np.uint8)


def mean_brightness(pixels):
    total = int(pixels.sum(dtype=np.int64))
    return round(total / pixels.size, 2)

