from decimal import Decimal

from pydantic import BaseModel, ConfigDict, field_validator


class LineItem(BaseModel):
    # pydantic v2 no longer converts numbers to str implicitly.
    model_config = ConfigDict(coerce_numbers_to_str=True)

    sku: str
    quantity: int
    unit_price: float
    note: str = ""

    @field_validator("quantity", mode="before")
    @classmethod
    def _truncate_quantity(cls, value):
        # pydantic v2 rejects floats with a fractional part for int fields;
        # the intended behaviour (as in v1) is to drop the fraction.
        if isinstance(value, (float, Decimal)) and not isinstance(value, bool):
            if math.isfinite(value):
                return math.trunc(value)
        return value


def parse_items(rows):
    return [LineItem(**row) for row in rows]


def item_labels(rows):
    return [f"{item.sku} x{item.quantity}" for item in parse_items(rows)]


def order_total(rows):
    return round(sum(item.quantity * item.unit_price for item in parse_items(rows)), 2)

