from pydantic import BaseModel, field_validator


class LineItem(BaseModel):
    sku: str
    quantity: int
    unit_price: float
    note: str = ""

    @field_validator("sku", "note", mode="before")
    @classmethod
    def _coerce_to_str(cls, value):
        # pydantic v1 coerced numbers to str; v2 does not by default.
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return str(value)
        return value

    @field_validator("quantity", mode="before")
    @classmethod
    def _truncate_quantity(cls, value):
        # pydantic v1 truncated floats (2.9 -> 2); v2 rejects fractional floats.
        if isinstance(value, float):
            return int(value)
        return value


def parse_items(rows):
    return [LineItem(**row) for row in rows]


def item_labels(rows):
    return [f"{item.sku} x{item.quantity}" for item in parse_items(rows)]


def order_total(rows):
    return round(sum(item.quantity * item.unit_price for item in parse_items(rows)), 2)

